 if(quality.value.verdict!=='approved'){
  const fix=await call('Correction sécurité',t,`Corrigeur ciblé. ${guard}\nSpécification:\n${t.spec}\nRapport impl:${JSON.stringify(imp.value)}\nRevue sécurité:${JSON.stringify(quality.value)}\nCorrige seulement défaut important/critique, test rouge/vert, fichiers autorisés, aucun Git. JSON conforme.`,t.review);
